// Port of xqy2006/ModelTrace fingerprint.py (MIT, see data/MODELTRACE-LICENSE).
// Keep math bit-compatible with the Python/numpy original; testdata/attribution.json
// holds reference outputs generated by the original implementation.

import type {
  AnswerDiagnostic,
  AttributionResult,
  ChallengeAnswer,
  ModelScore,
  ModelTraceBank,
} from './types';

export const VALUE_MIN = 1;
export const VALUE_MAX = 355;
export const DIMENSION = VALUE_MAX - VALUE_MIN + 1;
const ALPHA = 0.5;
const FAMILY_DISPLAY_NAMES: Record<string, string> = { gpt: 'GPT', claude: 'Claude' };

const DIGIT_RUN = /\d+/g;
const LETTER = /\p{L}/u;

export function parseNumbers(text: string): number[] {
  const runs: number[][] = [];
  let current: number[] = [];
  let previousEnd = 0;
  for (const match of text.matchAll(DIGIT_RUN)) {
    const start = match.index ?? 0;
    const separator = text.slice(previousEnd, start);
    const value = Number.parseInt(match[0], 10);
    if (current.length > 0 && [...separator].some((ch) => LETTER.test(ch))) {
      runs.push(current);
      current = [];
    }
    if (value >= VALUE_MIN && value <= VALUE_MAX) {
      current.push(value);
    }
    previousEnd = start + match[0].length;
  }
  if (current.length > 0) runs.push(current);
  if (runs.length === 0) return [];
  return runs.reduce((best, run) => (run.length > best.length ? run : best));
}

export function countNumbers(numbers: number[]): number[] {
  const counts = new Array<number>(DIMENSION).fill(0);
  for (const number of numbers) counts[number - VALUE_MIN] += 1;
  return counts;
}

function standardize(values: number[]): number[] {
  const mean = values.reduce((sum, v) => sum + v, 0) / values.length;
  const variance =
    values.reduce((sum, v) => sum + (v - mean) ** 2, 0) / values.length;
  const scale = Math.max(Math.sqrt(variance), 1e-12);
  return values.map((v) => (v - mean) / scale);
}

function hellingerFeature(counts: number[]): number[] {
  const smoothed = counts.map((c) => c + ALPHA);
  const total = smoothed.reduce((sum, v) => sum + v, 0);
  return smoothed.map((v) => Math.sqrt(v / total));
}

/** numpy array_split(values, 4): first n % 4 chunks get one extra element. */
function arraySplit4(values: number[]): number[][] {
  const base = Math.floor(values.length / 4);
  const remainder = values.length % 4;
  const chunks: number[][] = [];
  let offset = 0;
  for (let i = 0; i < 4; i += 1) {
    const size = base + (i < remainder ? 1 : 0);
    chunks.push(values.slice(offset, offset + size));
    offset += size;
  }
  return chunks;
}

/** numpy histogram(chunk, bins=16, range=(1.0, 356.0)). */
function histogram16(chunk: number[]): number[] {
  const bins = new Array<number>(16).fill(0);
  const width = (356.0 - 1.0) / 16;
  for (const value of chunk) {
    const index = Math.min(15, Math.floor((value - 1.0) / width));
    if (index >= 0) bins[index] += 1;
  }
  return bins;
}

function normalizeSqrt(counts: number[]): number[] {
  const smoothed = counts.map((c) => c + 0.5);
  const total = smoothed.reduce((sum, v) => sum + v, 0);
  return smoothed.map((v) => Math.sqrt(v / total));
}

function orderedBlockFeature(numbers: number[]): number[] {
  const pieces: number[] = [];
  for (const chunk of arraySplit4(numbers)) {
    pieces.push(...normalizeSqrt(histogram16(chunk)));
  }
  const lastDigits = new Array<number>(10).fill(0);
  for (const value of numbers) lastDigits[value % 10] += 1;
  pieces.push(...normalizeSqrt(lastDigits));
  return pieces;
}

function dot(a: number[], b: number[]): number {
  let sum = 0;
  for (let i = 0; i < a.length; i += 1) sum += a[i] * b[i];
  return sum;
}

function norm(values: number[]): number {
  return Math.sqrt(dot(values, values));
}

/** projected -= (projected @ basis.T) @ basis */
function projectOutNuisance(vector: number[], basis: number[][]): number[] {
  if (basis.length === 0) return vector;
  const coefficients = basis.map((row) => dot(vector, row));
  const out = vector.slice();
  for (let k = 0; k < basis.length; k += 1) {
    for (let i = 0; i < out.length; i += 1) {
      out[i] -= coefficients[k] * basis[k][i];
    }
  }
  return out;
}

/** vector @ centroids.T */
function matVec(centroids: number[][], vector: number[]): number[] {
  return centroids.map((row) => dot(row, vector));
}

function robustScoreCounts(
  counts: number[],
  bank: ModelTraceBank,
): { fused: number[]; nuisance: number[] } {
  const artifact = bank.robust.hellinger;
  const feature = hellingerFeature(counts);
  const projectedRaw = feature.map(
    (v, i) => (v - artifact.feature_mean[i]) / artifact.feature_scale[i],
  );
  const projected = projectOutNuisance(projectedRaw, artifact.nuisance_basis);
  const scale = Math.max(norm(projected), 1e-12);
  const unit = projected.map((v) => v / scale);
  const nuisance = standardize(matVec(artifact.centroids, unit));
  return { fused: standardize(nuisance), nuisance };
}

function orderedBlockScores(numbers: number[], bank: ModelTraceBank): number[] {
  const artifact = bank.robust.ordered_blocks;
  if (!artifact) throw new Error('ordered_blocks artifact missing');
  const feature = orderedBlockFeature(numbers);
  const standardizedFeature = feature.map(
    (v, i) => (v - artifact.feature_mean[i]) / artifact.feature_scale[i],
  );

  const featureNorm = Math.max(norm(standardizedFeature), 1e-12);
  const normalized = standardizedFeature.map((v) => v / featureNorm);
  const environmentScores = artifact.environment_centroids.map((centroids) =>
    matVec(centroids, normalized),
  );
  const modelCount = environmentScores[0]?.length ?? 0;
  const template = standardize(
    Array.from({ length: modelCount }, (_, m) =>
      Math.max(...environmentScores.map((scores) => scores[m])),
    ),
  );

  const projected = projectOutNuisance(
    standardizedFeature,
    artifact.nuisance_basis,
  );
  const projectedNorm = Math.max(norm(projected), 1e-12);
  const unit = projected.map((v) => v / projectedNorm);
  const nuisance = standardize(matVec(artifact.centroids, unit));
  return standardize(
    template.map((v, i) => 0.5 * v + 0.5 * nuisance[i]),
  );
}

function robustScoreNumbers(
  numbers: number[],
  bank: ModelTraceBank,
): { fused: number[]; nuisance: number[] } {
  const marginal = robustScoreCounts(countNumbers(numbers), bank);
  const artifact = bank.robust.ordered_blocks;
  const orderedWeight = artifact ? Number(artifact.weight ?? 0) : 0;
  if (!artifact || orderedWeight === 0) return marginal;
  const ordered = orderedBlockScores(numbers, bank);
  return {
    fused: marginal.fused.map(
      (v, i) => (1 - orderedWeight) * v + orderedWeight * ordered[i],
    ),
    nuisance: marginal.nuisance,
  };
}

function softmax(values: number[]): number[] {
  const maximum = Math.max(...values);
  const weights = values.map((v) => Math.exp(v - maximum));
  const total = weights.reduce((sum, v) => sum + v, 0);
  return weights.map((w) => w / total);
}

function jsSimilarity(left: number[], right: number[]): number {
  const leftTotal = left.reduce((sum, v) => sum + v, 0);
  const rightTotal = right.reduce((sum, v) => sum + v, 0) + ALPHA * DIMENSION;
  const p = left.map((v) => v / leftTotal);
  const q = right.map((v) => (v + ALPHA) / rightTotal);
  const midpoint = p.map((v, i) => (v + q[i]) / 2);

  const divergence = (values: number[], middle: number[]): number =>
    values.reduce(
      (sum, v, i) => (v ? sum + v * Math.log(v / middle[i]) : sum),
      0,
    );

  const js = (divergence(p, midpoint) + divergence(q, midpoint)) / 2;
  return 1 - Math.sqrt(js / Math.log(2));
}

export function analyzeOutputs(
  outputs: ChallengeAnswer[],
  bank: ModelTraceBank,
): AttributionResult {
  const modelIds = bank.models.map((m) => m.id);
  const valid: { counts: number[]; scores: number[]; nuisance: number[] }[] =
    [];
  const diagnostics: AnswerDiagnostic[] = [];

  outputs.forEach((item, index) => {
    const text = String(item.text ?? '');
    const expected = Math.trunc(item.expectedCount || 0);
    const numbers = parseNumbers(text);
    const minimum = expected ? Math.max(80, Math.ceil(expected * 0.55)) : 80;
    const accepted = numbers.length >= minimum;
    diagnostics.push({
      index,
      parsedNumbers: numbers.length,
      minimumNumbers: minimum,
      accepted,
    });
    if (accepted) {
      const components = robustScoreNumbers(numbers, bank);
      valid.push({
        counts: countNumbers(numbers),
        scores: components.fused,
        nuisance: components.nuisance,
      });
    }
  });

  if (valid.length === 0) {
    throw new Error('没有可用回答：回答中的有效数字不足，无法归因。');
  }

  const modelCount = modelIds.length;
  const combinedScores = Array.from(
    { length: modelCount },
    (_, m) =>
      valid.reduce((sum, item) => sum + item.scores[m], 0) / valid.length,
  );
  const combinedNuisance = Array.from(
    { length: modelCount },
    (_, m) =>
      valid.reduce((sum, item) => sum + item.nuisance[m], 0) / valid.length,
  );
  const calibrationKey = String(Math.min(valid.length, 3));
  const beta = Number(bank.calibration[calibrationKey].beta);
  const probabilities = softmax(combinedScores.map((v) => beta * v));
  const pooledCounts = Array.from({ length: DIMENSION }, (_, i) =>
    valid.reduce((sum, item) => sum + item.counts[i], 0),
  );
  const bankModels = new Map(bank.models.map((m) => [m.id, m]));
  const results: ModelScore[] = modelIds.map((modelId, index) => {
    const entry = bankModels.get(modelId);
    return {
      model: modelId,
      displayName: entry?.display_name ?? modelId,
      probability: probabilities[index],
      profileSimilarity: jsSimilarity(pooledCounts, entry?.counts ?? []),
      score: combinedScores[index],
      nuisanceScore: combinedNuisance[index],
      family: entry?.family ?? 'models',
      familyName:
        entry?.family_name ??
        FAMILY_DISPLAY_NAMES[entry?.family ?? ''] ??
        entry?.family ??
        'models',
      conditionalProbability: 0,
    };
  });
  results.sort((a, b) => b.probability - a.probability);

  const familyProbabilities = new Map<string, number>();
  for (const item of results) {
    familyProbabilities.set(
      item.family,
      (familyProbabilities.get(item.family) ?? 0) + item.probability,
    );
  }
  for (const item of results) {
    item.conditionalProbability =
      item.probability / (familyProbabilities.get(item.family) ?? 1);
  }
  let familyPrediction = results[0]?.family ?? 'models';
  let bestFamilyProbability = -1;
  for (const [family, probability] of familyProbabilities) {
    if (probability > bestFamilyProbability) {
      bestFamilyProbability = probability;
      familyPrediction = family;
    }
  }
  const familyPredictionName =
    results.find((r) => r.family === familyPrediction)?.familyName ??
    familyPrediction;

  return {
    prediction: results[0].model,
    predictionName: results[0].displayName,
    probability: results[0].probability,
    usedOutputs: valid.length,
    results,
    diagnostics,
    calibration: {
      queries: calibrationKey,
      beta,
      cvAccuracy: bank.calibration[calibrationKey].cv_accuracy,
    },
    familyPrediction,
    familyPredictionName,
    familyProbability: bestFamilyProbability,
  };
}
